svg.script:
(function() {
  var root = document.querySelector('.a12p18-hero-root');
  if (!root) return;

  var mode = 'study'; // 'study' or 'quiz'
  var activeId = 'pb';

  // Data dictionary for anatomical structures
  var dataMap = {
    'pb': {
      title: 'CORPO PERINEAL (CENTRO TENDÍNEO)',
      territory: 'Ponto de Convergência Central dos 4 Músculos Perineais',
      tri: 'both',
      color: 'var(--a12-ouro, #F3BE5B)',
      badges: [true, true, true, true],
      desc: [
        'O Corpo Perineal é o nódulo fibromuscular central situado',
        'na divisa entre o Trígono Urogenital (anterior) e Anal (posterior).',
        'Recebe a inserção direta de 3 músculos urogenitais e 1 músculo',
        'anal, fornecendo sustentação estática ao assoalho pélvico.'
      ],
      clinical: [
        'Lacerações de 3º/4º grau ou episiotomia mediana seccionam este ponto,',
        'comprometendo a convergência e predispondo a prolapso e incontinência.'
      ]
    },
    'isquiocavernoso': {
      title: 'M. ISQUIOCAVERNOSO',
      territory: 'Trígono Urogenital (Território Anterior)',
      tri: 'ug',
      color: 'var(--a12-isquiocavernoso, #A978C7)',
      badges: [false, true, false, false],
      desc: [
        'Fixa-se às tuberosidades isquiáticas e ramos isquiopúbicos,',
        'envolvendo os crura do clitóris/pênis.',
        'Emite fibras mediais que convergem para a fáscia e corpo perineal,',
        'auxiliando na manutenção da ereção e estabilização lateral.'
      ],
      clinical: [
        'Mantém o ingurgitamento erétil ao comprimir a drenagem venosa.',
        'Raramente seccionado na episiotomia mediolateral.'
      ]
    },
    'bulboesponjoso': {
      title: 'M. BULBOESPONJOSO',
      territory: 'Trígono Urogenital (Território Anterior)',
      tri: 'ug',
      color: 'var(--a12-bulboesponjoso, #F08A65)',
      badges: [true, false, false, false],
      desc: [
        'Cobre o bulbo do vestíbulo / bulbo peniano na linha média.',
        'Suas fibras posteriores convergem diretamente para o Corpo Perineal.',
        'Atua na contração do introitus vaginal e esvaziamento uretral.'
      ],
      clinical: [
        'Envolvido diretamente nas episiotomias medianas e mediolaterais.',
        'Sua reconstituição adequada é vital para a função sexual e continência.'
      ]
    },
    'transverso': {
      title: 'M. TRANSVERSO SUPERFICIAL',
      territory: 'Trígono Urogenital (Limite com Trígono Anal)',
      tri: 'ug',
      color: 'var(--a12-transverso-superficial, #55B889)',
      badges: [false, false, true, false],
      desc: [
        'Corre horizontalmente da tuberosidade isquiática ao Corpo Perineal.',
        'Forma a margem posterior livre da Membrana Perineal.',
        'Fixa o Corpo Perineal no plano transversal da linha bituberosa.'
      ],
      clinical: [
        'Músculo chave seccionado na episiotomia mediolateral.',
        'Sua sutura correta restabelece a tensão transversal do períneo.'
      ]
    },
    'esfincter': {
      title: 'M. ESFÍNCTER EXTERNO DO ÂNUS',
      territory: 'Trígono Anal (Território Posterior)',
      tri: 'an',
      color: 'var(--a12-esfincter-anal, #D85C6A)',
      badges: [false, false, false, true],
      desc: [
        'Único músculo superficial situado no Trígono Anal posterior.',
        'Envolve o canal anal; suas fibras anteriores fixam-se no Corpo Perineal,',
        'e as posteriores anco-ram-se no ligamento anocóccigeo / cóccix.'
      ],
      clinical: [
        'Lacerações perineais de 3º grau atingem este esfíncter.',
        'A lesão não reparada leva à incontinência fecal e de flatos.'
      ]
    },
    'tri-ug': {
      title: 'TRÍGONO UROGENITAL',
      territory: 'Região Anterior do Períneo (Sínfise a Linha Bituberosa)',
      tri: 'ug',
      color: 'var(--a12-trigono-urogenital, #EF7582)',
      badges: [true, true, true, false],
      desc: [
        'Compreende a metade anterior do diamante perineal.',
        'Contém a Membrana Perineal e 3 músculos superficiais:',
        'M. Isquiocavernoso, M. Bulboesponjoso e M. Transverso Superficial.',
        'Atravessado pela uretra e vagina / estrutura erétil.'
      ],
      clinical: [
        'Área de maior estiramento e intervenção obstétrica intraparto.'
      ]
    },
    'tri-an': {
      title: 'TRÍGONO ANAL',
      territory: 'Região Posterior do Períneo (Linha Bituberosa ao Cóccix)',
      tri: 'an',
      color: 'var(--a12-trigono-anal, #6FA8D6)',
      badges: [false, false, false, true],
      desc: [
        'Compreende a metade posterior do diamante perineal.',
        'Contém o Canal Anal, Fossa Isquioanal e 1 músculo principal:',
        'Esfíncter Externo do Ânus, além do complexo elevador do ânus profundo.'
      ],
      clinical: [
        'Sua integridade evita o surgimento de fístulas anorretais e prolapsos.'
      ]
    }
  };

  function updatePanel(key) {
    var item = dataMap[key] || dataMap['pb'];
    root.setAttribute('data-active', key);
    root.setAttribute('data-active-tri', item.tri);

    var titleEl = document.getElementById('a12p18-hero-panel-title');
    var territoryEl = document.getElementById('a12p18-hero-panel-territory');
    var indicatorEl = document.getElementById('a12p18-hero-panel-indicator');

    if (mode === 'quiz' && key !== 'pb' && key !== 'tri-ug' && key !== 'tri-an') {
      titleEl.textContent = 'ESTRUTURA SELECIONADA (MODO QUIZ)';
      territoryEl.textContent = 'Identifique a estrutura e sua convergência';
      indicatorEl.style.fill = '#A8A2B5';
    } else {
      titleEl.textContent = item.title;
      territoryEl.textContent = item.territory;
      indicatorEl.style.fill = item.color;
    }

    // Update descriptions
    for (var i = 1; i <= 4; i++) {
      var descEl = document.getElementById('a12p18-hero-panel-desc-' + i);
      if (descEl) {
        descEl.textContent = item.desc[i - 1] || '';
      }
    }

    // Update clinical
    var clin1 = document.getElementById('a12p18-hero-panel-clinical-1');
    var clin2 = document.getElementById('a12p18-hero-panel-clinical-2');
    if (clin1) clin1.textContent = item.clinical[0] || '';
    if (clin2) clin2.textContent = item.clinical[1] || '';

    // Update badges
    var badgeIds = ['bulbo', 'isq', 'trans', 'esf'];
    badgeIds.forEach(function(bId, idx) {
      var badgeEl = document.getElementById('a12p18-hero-badge-' + bId);
      if (badgeEl) {
        badgeEl.style.opacity = item.badges[idx] ? '1' : '0.25';
      }
    });
  }

  // Attach click listeners
  var targets = [
    { id: 'a12p18-hero-target-pb', key: 'pb' },
    { id: 'a12p18-hero-m-isquiocavernoso', key: 'isquiocavernoso' },
    { id: 'a12p18-hero-m-bulboesponjoso', key: 'bulboesponjoso' },
    { id: 'a12p18-hero-m-transverso', key: 'transverso' },
    { id: 'a12p18-hero-m-esfincter', key: 'esfincter' },
    { id: 'a12p18-hero-target-tri-ug', key: 'tri-ug' },
    { id: 'a12p18-hero-target-tri-an', key: 'tri-an' }
  ];

  targets.forEach(function(t) {
    var el = document.getElementById(t.id);
    if (el) {
      el.addEventListener('click', function() {
        updatePanel(t.key);
      });
      el.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          updatePanel(t.key);
        }
      });
    }
  });

  // Mode Toggle Button
  var btnMode = document.getElementById('a12p18-hero-btn-mode');
  var modeText = document.getElementById('a12p18-hero-mode-text');
  if (btnMode) {
    btnMode.addEventListener('click', function() {
      mode = (mode === 'study') ? 'quiz' : 'study';
      root.setAttribute('data-mode', mode);
      if (modeText) {
        modeText.textContent = (mode === 'study') ? 'Modo: Anatomia (Rótulos)' : 'Modo: Reconhecimento';
      }
      updatePanel(root.getAttribute('data-active') || 'pb');
    });
  }

  // Reset Button
  var btnReset = document.getElementById('a12p18-hero-btn-reset');
  if (btnReset) {
    btnReset.addEventListener('click', function() {
      updatePanel('pb');
    });
  }

  // Initial panel setup
  updatePanel('pb');
})();
